func NewAsPathPrependValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (AsPathPrependValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing AsPathPrependValue Attribute Value",
				"While creating a AsPathPrependValue value, a missing attribute value was detected. "+
					"A AsPathPrependValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("AsPathPrependValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid AsPathPrependValue Attribute Type",
				"While creating a AsPathPrependValue value, an invalid attribute value was detected. "+
					"A AsPathPrependValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("AsPathPrependValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("AsPathPrependValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra AsPathPrependValue Attribute Value",
				"While creating a AsPathPrependValue value, an extra attribute value was detected. "+
					"A AsPathPrependValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra AsPathPrependValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewAsPathPrependValueUnknown(), diags
	}

	asnAttribute, ok := attributes["asn"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`asn is missing from object`)

		return NewAsPathPrependValueUnknown(), diags
	}

	asnVal, ok := asnAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`asn expected to be basetypes.StringValue, was: %T`, asnAttribute))
	}

	countAttribute, ok := attributes["count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`count is missing from object`)

		return NewAsPathPrependValueUnknown(), diags
	}

	countVal, ok := countAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`count expected to be basetypes.Int64Value, was: %T`, countAttribute))
	}

	if diags.HasError() {
		return NewAsPathPrependValueUnknown(), diags
	}

	return AsPathPrependValue{
		Asn:   asnVal,
		Count: countVal,
		state: attr.ValueStateKnown,
	}, diags
}

