func (v Bgp1Value) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 8)

	var val tftypes.Value
	var err error

	attrTypes["as_path_prepend"] = basetypes.ObjectType{
		AttrTypes: AsPathPrepend1Value{}.AttributeTypes(ctx),
	}.TerraformType(ctx)
	attrTypes["as_path_remove"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["as_path_replace"] = basetypes.ListType{
		ElemType: types.Int64Type,
	}.TerraformType(ctx)
	attrTypes["communities"] = basetypes.ObjectType{
		AttrTypes: Communities1Value{}.AttributeTypes(ctx),
	}.TerraformType(ctx)
	attrTypes["med"] = basetypes.ObjectType{
		AttrTypes: Med1Value{}.AttributeTypes(ctx),
	}.TerraformType(ctx)
	attrTypes["next_hop"] = basetypes.ObjectType{
		AttrTypes: NextHop1Value{}.AttributeTypes(ctx),
	}.TerraformType(ctx)
	attrTypes["set_local_preference"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["set_origin"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 8)

		val, err = v.AsPathPrepend1.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["as_path_prepend"] = val

		val, err = v.AsPathRemove.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["as_path_remove"] = val

		val, err = v.AsPathReplace.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["as_path_replace"] = val

		val, err = v.Communities1.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["communities"] = val

		val, err = v.Med1.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["med"] = val

		val, err = v.NextHop1.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["next_hop"] = val

		val, err = v.SetLocalPreference.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["set_local_preference"] = val

		val, err = v.SetOrigin.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["set_origin"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

