func (v Bgp2Value) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var asPathMatch basetypes.ObjectValue

	if v.AsPathMatch.IsNull() {
		asPathMatch = types.ObjectNull(
			AsPathMatchValue{}.AttributeTypes(ctx),
		)
	}

	if v.AsPathMatch.IsUnknown() {
		asPathMatch = types.ObjectUnknown(
			AsPathMatchValue{}.AttributeTypes(ctx),
		)
	}

	if !v.AsPathMatch.IsNull() && !v.AsPathMatch.IsUnknown() {
		asPathMatch = types.ObjectValueMust(
			AsPathMatchValue{}.AttributeTypes(ctx),
			v.AsPathMatch.Attributes(),
		)
	}

	var nextHop2 basetypes.ObjectValue

	if v.NextHop2.IsNull() {
		nextHop2 = types.ObjectNull(
			NextHop2Value{}.AttributeTypes(ctx),
		)
	}

	if v.NextHop2.IsUnknown() {
		nextHop2 = types.ObjectUnknown(
			NextHop2Value{}.AttributeTypes(ctx),
		)
	}

	if !v.NextHop2.IsNull() && !v.NextHop2.IsUnknown() {
		nextHop2 = types.ObjectValueMust(
			NextHop2Value{}.AttributeTypes(ctx),
			v.NextHop2.Attributes(),
		)
	}

	var evpnRouteTypesVal basetypes.ListValue
	switch {
	case v.EvpnRouteTypes.IsUnknown():
		evpnRouteTypesVal = types.ListUnknown(types.Int64Type)
	case v.EvpnRouteTypes.IsNull():
		evpnRouteTypesVal = types.ListNull(types.Int64Type)
	default:
		var d diag.Diagnostics
		evpnRouteTypesVal, d = types.ListValue(types.Int64Type, v.EvpnRouteTypes.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"as_path_match": basetypes.ObjectType{
				AttrTypes: AsPathMatchValue{}.AttributeTypes(ctx),
			},
			"community_set": basetypes.StringType{},
			"evpn_route_types": basetypes.ListType{
				ElemType: types.Int64Type,
			},
			"next_hop": basetypes.ObjectType{
				AttrTypes: NextHop2Value{}.AttributeTypes(ctx),
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"as_path_match": basetypes.ObjectType{
			AttrTypes: AsPathMatchValue{}.AttributeTypes(ctx),
		},
		"community_set": basetypes.StringType{},
		"evpn_route_types": basetypes.ListType{
			ElemType: types.Int64Type,
		},
		"next_hop": basetypes.ObjectType{
			AttrTypes: NextHop2Value{}.AttributeTypes(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"as_path_match":    asPathMatch,
			"community_set":    v.CommunitySet,
			"evpn_route_types": evpnRouteTypesVal,
			"next_hop":         nextHop2,
		})

	return objVal, diags
}

